<?php
declare(strict_types=1);

/**
 * Zeichen-Hilfen für Datei- und Ordnernamen.
 * text_nfc(): zerlegte Buchstaben („e“ + Akzent, wie aus macOS oder dem Web) zu einem Zeichen zusammensetzen –
 * sonst gibt es zwei gleich aussehende, aber verschiedene Namen. Mit der PHP-Erweiterung intl über Normalizer,
 * ohne sie über eine Tabelle der lateinischen Buchstaben mit Akzenten (deckt Namen in Musiksammlungen ab).
 */
function text_nfc(string $s): string
{
    if (class_exists('Normalizer')) {
        $n = Normalizer::normalize($s, Normalizer::FORM_C);
        return is_string($n) ? $n : $s;
    }
    if (!preg_match('/[\x{0300}-\x{036F}]/u', $s)) {
        return $s;
    }
    return strtr($s, text_akzent_tabelle());
}

