/** Streng: nur ASCII (ä → ae, é → e, ß → ss; Emojis und Unübersetzbares fallen weg) */
function text_ascii(string $s): string
{
    $s = strtr(text_nfc($s), ['ä' => 'ae', 'ö' => 'oe', 'ü' => 'ue', 'Ä' => 'Ae', 'Ö' => 'Oe', 'Ü' => 'Ue', 'ß' => 'ss', 'ẞ' => 'SS',
        '“' => "'", '”' => "'", '„' => "'", '‘' => "'", '’' => "'", '‚' => "'", '«' => "'", '»' => "'", '–' => '-', '—' => '-', '…' => '...']);
    // Akzente weg: é → e (zusammengesetzte Zeichen über die Tabelle rückwärts, übrig gebliebene Akzentzeichen entfernen)
    static $grund = null;
    if ($grund === null) {
        $grund = [];
        foreach (text_akzent_tabelle() as $zerlegt => $fertig) {
            $grund[$fertig] = mb_substr($zerlegt, 0, 1);
        }
        $grund += ['æ' => 'ae', 'Æ' => 'Ae', 'ø' => 'o', 'Ø' => 'O', 'œ' => 'oe', 'Œ' => 'Oe', 'đ' => 'd', 'Đ' => 'D', 'ł' => 'l', 'Ł' => 'L',
            'ð' => 'd', 'Ð' => 'D', 'þ' => 'th', 'Þ' => 'Th', 'ı' => 'i', '¿' => '', '¡' => ''];
    }
    $s = (string) preg_replace('/[\x{0300}-\x{036F}]/u', '', strtr($s, $grund));
    $a = function_exists('iconv') ? @iconv('UTF-8', 'ASCII//TRANSLIT//IGNORE', $s) : false;
    if (!is_string($a)) {
        $a = (string) preg_replace('/[^\x20-\x7E]/', '', $s);
    }
    return str_replace('?', '', $a); // iconv setzt „?“ für Unübersetzbares
}
